# Dict comprehension
square_dict = {x: x**2 for x in range(1, 6)}
print(square_dict)   # {1:1, 2:4, 3:9, 4:16, 5:25}

# Invert a dict
original = {'a': 1, 'b': 2, 'c': 3}
inverted = {v: k for k, v in original.items()}
print(inverted)      # {1:'a', 2:'b', 3:'c'}

# Set comprehension — unique lengths
words = ['hi','hello','hey','world']
unique_lens = {len(w) for w in words}
print(unique_lens)   # {2, 5}

# Generator expression — memory efficient
gen = (x**2 for x in range(1000000))  # no list created
print(next(gen))     # 0
print(next(gen))     # 1
print(sum(x**2 for x in range(10)))  # 285

# Traversal
def traverse(arr):
    for i, val in enumerate(arr):
        print(f"Index {i}: {val}")

# Linear search — O(n)
def linear_search(arr, target):
    for i, val in enumerate(arr):
        if val == target:
            return i
    return -1

# Binary search — O(log n) — requires sorted array
def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

arr = [1, 3, 5, 7, 9, 11, 13]
print(binary_search(arr, 7))    # 3
print(binary_search(arr, 6))    # -1

# Insertion at index — O(n)
def insert_at(arr, index, val):
    arr.insert(index, val)
    return arr

# Deletion by value — O(n)
def delete_val(arr, val):
    if val in arr:
        arr.remove(val)
    return arr

# Two-pointer — find pair with given sum in sorted array
def two_sum_sorted(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        s = arr[left] + arr[right]
        if s == target:
            return (left, right)
        elif s < target:
            left += 1
        else:
            right -= 1
    return None

print(two_sum_sorted([1,2,3,4,6], 6))  # (1, 3) → 2+4

# Sliding window — max sum subarray of size k
def max_sum_window(arr, k):
    window = sum(arr[:k])
    max_sum = window
    for i in range(k, len(arr)):
        window += arr[i] - arr[i-k]
        max_sum = max(max_sum, window)
    return max_sum

print(max_sum_window([2,1,5,1,3,2], 3))  # 9 (5+1+3)
